select *
from t_csys_course where id in

    #{id}

SELECT tscs.term as term_id, sum(cc.credit) as credit_count FROM t_csys_training_scheme_course_schedule tscs left join t_csys_course cc on cc.id = tscs.course_id WHERE scheme_id in
#{schemeId}
and tscs.checked = 1 and tscs.sysflag = 0 GROUP BY tscs.term

SELECT tscs.term AS term_id, sum(IF(tsrc.course_type_id = 1, 1, 0)) AS public_required_course_count, sum(IF(tsrc.course_type_id = 2, 1, 0)) AS subject_required_course_count, sum(IF(tsrc.course_type_id = 3, 1, 0)) AS speciality_required_course_count, sum(IF(tsrc.course_type_id = 4, 1, 0)) AS public_elective_course_count, sum(IF(tsrc.course_type_id = 5, 1, 0)) AS subject_elective_course_count FROM t_csys_training_scheme_course_schedule tscs LEFT JOIN t_csys_course cc ON cc.id = tscs.course_id LEFT JOIN t_csys_training_scheme_ref_course tsrc ON tsrc.course_id = tscs.course_id AND tsrc.scheme_id = tscs.scheme_id WHERE tscs.scheme_id in
#{schemeId}
and tscs.sysflag = 0 and tscs.checked = 1 GROUP BY tscs.term

