select ts.*, stc.name as stc_top_name, instance.id instanceId, instance.name instanceName, instance.version instanceVersion, tsc.name as category_name, csm.name as major_name, sub_csm.name as subMajorName, sub_csm.id as subMajorId from t_csys_training_scheme ts left join t_csys_std_cultivation stc on stc.id = ts.standard_id and stc.sysflag = '0' left join t_csys_teaching_programme_instance instance on ts.instance_id = instance.id left join t_csys_training_scheme_category tsc on tsc.id = ts.category_id left join t_csys_std_major csm on csm.id = ts.major_id left join t_csys_scheme_ref_major srm on srm.scheme_id = ts.id left join t_csys_std_major sub_csm on sub_csm.id = srm.major_id where ts.id in
#{id}
order by ${databaseProp} ${order}
order by ts.id desc
